package main
import("context";"encoding/json";"log/slog";"net/http";"os";"strings";"time";"github.com/flowpilot/flowpilot/internal/domain";"github.com/flowpilot/flowpilot/internal/storage")
func main(){ctx:=context.Background();st,e:=storage.Open(ctx,os.Getenv("DATABASE_URL"));if e!=nil{slog.Error("database unavailable","error",e);os.Exit(1)};defer st.Close();mux:=http.NewServeMux();mux.HandleFunc("/healthz",func(w http.ResponseWriter,r *http.Request){json.NewEncoder(w).Encode(map[string]string{"status":"ok"})});mux.HandleFunc("/hooks/",webhook(st));mux.HandleFunc("/api/v1/workflows",func(w http.ResponseWriter,r *http.Request){if r.Method=="POST"{var q struct{Name,Description string};if json.NewDecoder(r.Body).Decode(&q)!=nil||strings.TrimSpace(q.Name)==""{problem(w,400,"name is required");return};x,_:=st.CreateWorkflow(r.Context(),q.Name,q.Description);respond(w,201,x);return};if r.Method=="GET"{x,e:=st.ListWorkflows(r.Context());respondErr(w,e);respond(w,200,x);return};problem(w,405,"method not allowed")});mux.HandleFunc("/api/v1/workflows/",func(w http.ResponseWriter,r *http.Request){p:=strings.Split(strings.TrimPrefix(r.URL.Path,"/api/v1/workflows/"),"/");id:=p[0];if len(p)==2&&p[1]=="draft"&&r.Method=="PUT"{var q struct{Revision int64 `json:"revision"`;Graph domain.Graph `json:"graph"`};if json.NewDecoder(r.Body).Decode(&q)!=nil{problem(w,400,"invalid JSON");return};if es:=domain.ValidateGraph(q.Graph);len(es)>0{respond(w,422,map[string]any{"errors":es});return};x,e:=st.UpdateDraft(r.Context(),id,q.Revision,q.Graph);respondErr(w,e);respond(w,200,x);return};if len(p)==2&&p[1]=="publish"&&r.Method=="POST"{x,e:=st.Publish(r.Context(),id);respondErr(w,e);respond(w,200,x);return};if len(p)==2&&p[1]=="executions"&&r.Method=="POST"{var q struct{Input map[string]any `json:"input"`};json.NewDecoder(r.Body).Decode(&q);x,e:=st.Start(r.Context(),id,q.Input);respondErr(w,e);respond(w,202,x);return};if len(p)==2&&p[1]=="executions"&&r.Method=="GET"{x,e:=st.ListExecutions(r.Context());respondErr(w,e);respond(w,200,x);return};problem(w,404,"not found")});mux.HandleFunc("/api/v1/executions/",func(w http.ResponseWriter,r *http.Request){if !strings.HasSuffix(r.URL.Path,"/cancel")||r.Method!="POST"{problem(w,404,"not found");return};e:=st.Cancel(r.Context(),strings.TrimSuffix(strings.TrimPrefix(r.URL.Path,"/api/v1/executions/"),"/cancel"));respondErr(w,e);respond(w,204,nil)});srv:=http.Server{Addr:env("FLOWPILOT_API_ADDR",":8080"),Handler:cors(requestID(mux)),ReadHeaderTimeout:5*time.Second};slog.Info("api listening","addr",srv.Addr);slog.Error("server stopped","error",srv.ListenAndServe())}
func respond(w http.ResponseWriter,s int,v any){w.Header().Set("Content-Type","application/json");w.WriteHeader(s);if v!=nil{json.NewEncoder(w).Encode(v)}};func problem(w http.ResponseWriter,s int,d string){respond(w,s,map[string]any{"error":d})};func respondErr(w http.ResponseWriter,e error){if e!=nil{problem(w,500,e.Error())}};func env(k,d string)string{if v:=os.Getenv(k);v!=""{return v};return d};func requestID(n http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("X-Request-Id",time.Now().UTC().Format("20060102150405.000000000"));n.ServeHTTP(w,r)})}
func webhook(store *storage.Store) http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){if r.Method!="POST"{problem(w,405,"method not allowed");return};var payload map[string]any;if json.NewDecoder(http.MaxBytesReader(w,r.Body,1<<20)).Decode(&payload)!=nil{problem(w,400,"body must be JSON under 1 MiB");return};payload["headers"]=r.Header;payload["query"]=r.URL.Query();x,e:=store.StartWebhook(r.Context(),strings.TrimPrefix(r.URL.Path,"/hooks/"),payload);if e!=nil{problem(w,404,"webhook not found");return};respond(w,202,map[string]any{"executionId":x.ID,"status":x.Status})}}
func cors(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){w.Header().Set("Access-Control-Allow-Origin","http://localhost:3100");w.Header().Set("Access-Control-Allow-Headers","Content-Type");w.Header().Set("Access-Control-Allow-Methods","GET,POST,PUT,OPTIONS");if r.Method==http.MethodOptions{w.WriteHeader(http.StatusNoContent);return};next.ServeHTTP(w,r)})}
